/** Brand words that must survive translation, per key. */
const BRAND_GUARD: Record<string, string[]> = {
  numberLabel: ["Nabil"], enable: ["Nabil"], enableHint: ["Nabil"], greetingHint: ["Nabil"],
  voiceHint: ["Nabil"], capabilities: ["Nabil"], afterHours: ["Nabil"], transferHint: ["Nabil"],
  noCalls: ["Nabil"], shipdayNote: ["ShipDay"],
};

function get(obj: any, parts: string[]) {
  return parts.reduce((o, k) => (o == null ? o : o[k]), obj);
}

function main() {
  const files = fs.readdirSync(DIR).filter((f) => f.endsWith(".json"));
  const locales = files.map((f) => f.replace(/\.json$/, ""));
  const enSrc = get(JSON.parse(fs.readFileSync(path.join(DIR, "en.json"), "utf8")), NS) as Pack;
  const KEYS = Object.keys(enSrc);

  const problems: string[] = [];
  for (const loc of locales) {
    if (loc === "en") continue;
    const pack = PACKS[loc];
    if (!pack) { problems.push(`missing pack for "${loc}"`); continue; }
    for (const k of KEYS) {
      const v = pack[k];
      if (v === undefined || !String(v).trim()) { problems.push(`${loc}.${k} missing/empty`); continue; }
      for (const brand of BRAND_GUARD[k] ?? []) {
        if (!v.includes(brand)) problems.push(`${loc}.${k} dropped the brand name "${brand}"`);
      }
      const args = [...String(enSrc[k]).matchAll(/\{(\w+)[,}]/g)].map((m) => m[1]);
      for (const a of args) {
        if (!new RegExp(`\\{${a}[,}]`).test(v)) problems.push(`${loc}.${k} lost {${a}}`);
      }
    }
    for (const k of Object.keys(pack)) {
      if (!KEYS.includes(k)) problems.push(`${loc}.${k} is not a key in en.json`);
    }
  }
  if (problems.length) {
    console.error("❌ ABORTED — nothing written:");
    for (const p of problems) console.error("   " + p);
    process.exit(1);
  }

  let n = 0;
  for (const loc of locales) {
    if (loc === "en") continue;
    const file = path.join(DIR, `${loc}.json`);
    const json = JSON.parse(fs.readFileSync(file, "utf8"));
    const target = get(json, NS);
    for (const k of KEYS) target[k] = PACKS[loc][k];
    if (WRITE) fs.writeFileSync(file, JSON.stringify(json, null, 2) + "\n", "utf8");
    n++;
  }
  console.log(`${WRITE ? "✅ wrote" : "🔍 dry run —"} ${KEYS.length} keys × ${n} locales (en untouched)`);
  if (!WRITE) console.log("   re-run with --write to apply");
}

main();
